    /// Album rules saved before Album offered only "is" / "isn't" (≥, between… from when it was a
    /// number field) always meant "isn't" to the matcher; upgrading says so, so they check again.
    #[test]
    fn old_album_operators_upgrade_to_isnt() {
        let mut r = rs(json!({"rules": [
            {"field": "album", "op": "gte", "value": 1},
            {"field": "album", "op": "is", "value": 1},
            {"field": "rating", "op": "gte", "value": 3},
            {"group": {"rules": [{"field": "album", "op": "between", "value": [1, 2]}]}}
        ]}));
        r.upgrade();
        let ops = serde_json::to_value(&r).unwrap().to_string();
        assert!(ops.contains(r#""field":"album","op":"isNot","value":1"#), "{ops}");
        assert!(ops.contains(r#""field":"album","op":"is","value":1"#), "{ops}");
        assert!(ops.contains(r#""field":"rating","op":"gte""#), "other fields keep theirs: {ops}");
        assert!(ops.contains(r#""field":"album","op":"isNot","value":[1,2]"#), "inside groups too: {ops}");
    }

    /// Besides its English message (for agents), a problem names its field and the kind of issue,
    /// so the editor can show "Title: needs something to look for" in any language. Every issue
    /// has its own short text.
    #[test]
    fn problems_name_their_field_and_issue() {
        let cat = Catalog::new();
        let check = |rules: serde_json::Value| rs(json!({"rules": rules})).check(&cat);
        let p = check(json!([{"field": "title", "op": "contains", "value": ""}]));
        assert_eq!((p[0].field.as_deref(), p[0].issue), (Some("title"), Issue::NeedsTextOrEmpty));
        let p = check(json!([{"field": "title", "op": "isNot", "value": ""}]));
        assert_eq!(p[0].issue, Issue::NeedsTextOrNotEmpty);
        // keywords and people say "are empty", and so does their hint
        let p = check(json!([{"field": "keywords", "op": "contains", "value": ""}, {"field": "person", "op": "notContains", "value": " "}]));
        assert_eq!((p[0].issue, p[1].issue), (Issue::NeedsNamesOrEmpty, Issue::NeedsNamesOrNotEmpty));
        assert!(p[0].issue.text().contains("“are empty”") && p[0].message.contains("“are empty”"));
        let p = check(json!([{"field": "rating", "op": "is", "value": 9}, {"group": {"rules": []}}]));
        assert_eq!((p[0].field.as_deref(), p[0].issue), (Some("rating"), Issue::NoRatingMatches));
        assert_eq!((p[1].field.as_deref(), p[1].issue), (None, Issue::EmptyGroup));
        let p = check(json!([{"field": "captureDate", "op": "between", "value": ["2026-12", "2026-01"]}]));
        assert_eq!(p[0].issue, Issue::DatesReversed);
        let p = check(json!([{"field": "album", "op": "is", "value": null}]));
        assert_eq!(p[0].issue, Issue::ChooseAlbum);
        let mut texts: Vec<&str> = Issue::ALL.iter().map(|i| i.text()).collect();
        assert!(texts.iter().all(|t| !t.is_empty()));
        texts.sort_unstable();
        texts.dedup();
        assert_eq!(texts.len(), Issue::ALL.len(), "each issue reads differently");
    }

    /// A rule date reads one way for the check and the matcher: a space works as the "T"
    /// ("2026-10-01 10:00" matches a photo taken then). Imported capture times can carry fractions
    /// of a second and a time zone (EXIF SubSecTime / OffsetTime: "…T10:00:00.250+02:00"), so a
    /// rule may too, after the seconds; anywhere else they are no date.
    #[test]
    fn rule_dates_have_one_reading() {
        let cat = Catalog::new();
        let mut p = photo(1);
        p.captured = Some("2026-10-01T10:00:00".into());
        let rule = |op: &str, v: serde_json::Value| rs(json!({"rules": [{"field": "captureDate", "op": op, "value": v}]}));
        for (op, v) in [
            ("is", json!("2026-10-01 10:00")),
            ("is", json!(" 2026-10-01T10 ")),
            ("between", json!(["2026-10-01 09:00", "2026-10-01 11:00"])),
            ("after", json!("2026-10-01 09:59")),
        ] {
            let r = rule(op, v.clone());
            assert!(r.check(&cat).is_empty() && r.matches(&p, &cat), "{op} {v}");
        }
        // a capture time with a fraction and a zone, as imports write it
        let mut zoned = photo(2);
        zoned.captured = Some("2026-08-14T10:00:00.250+02:00".into());
        for v in ["2026-08-14T10:00:00.250", "2026-08-14T10:00:00.250+02:00", "2026-08-14T10:00:00"] {
            let r = rule("is", json!(v));
            assert!(r.check(&cat).is_empty() && r.matches(&zoned, &cat), "{v}");
        }
        assert!(rule("is", json!("2026-08-14T10:00:00Z")).check(&cat).is_empty());
        for v in [
            "2026-8-14",
            "2026-08-14T1",
            "2026-08-14X10",
            "26-08-14",
            "2026-08-14T25:00",
            "2026-08-14Z",
            "2026-08-14 10:00-05:00",
            "2026-08-14T10:00:00.",
            "2026-08-14T10:00:00+2",
        ] {
            let p = rule("is", json!(v)).check(&cat);
            assert_eq!(p.first().map(|p| p.issue), Some(Issue::NeedsDate), "{v}");
        }
        assert_eq!(rule_date("2026-10-01 10:00"), Ok("2026-10-01T10:00".to_string()));
        assert_eq!(rule_date("2026"), Ok("2026".to_string()));
    }

    /// The field menu shows every rule field once: at the top level or in exactly one group,
    /// and [`FIELDS`] lists them in menu order.
    #[test]
    fn every_field_is_in_the_menu_exactly_once() {
        let menu: Vec<&str> = TOP_LEVEL_FIELDS.iter().chain(FIELD_GROUPS.iter().flat_map(|g| g.1.iter())).copied().collect();
        let fields: Vec<&str> = FIELDS.iter().map(|f| f.0).collect();
        assert_eq!(menu, fields, "the menu and FIELDS list the same fields in the same order");
        for (label, group) in FIELD_GROUPS {
            assert!(!group.is_empty(), "group {label} is empty");
        }
        let mut labels: Vec<&str> = FIELD_GROUPS.iter().map(|g| g.0).collect();
        labels.dedup();
        assert_eq!(labels.len(), FIELD_GROUPS.len(), "group labels are unique");
    }

    /// Related fields sit together: all the file fields, all the camera (EXIF) fields, all the
    /// dates, all the keyword fields.
    #[test]
    fn related_fields_share_a_group() {
        let same = |fields: &[&str], group: &str| {
            for f in fields {
                assert_eq!(field_group(f), Some(group), "{f}");
            }
        };
        same(&["fileName", "extension", "filePath", "kind", "format", "duration"], "File");
        same(&["album", "virtualCopy", "copyName", "stacked"], "Source");
        same(&["longEdge", "shortEdge", "aspect", "megapixels"], "Size");
        same(&["edited", "cropped", "treatment"], "Develop");
        same(&["camera", "lens", "focalLength", "aperture", "shutterSpeed", "iso"], "Camera Info");
        same(&["captureDate", "importDate", "editDate"], "Date");
        same(&["keywords", "keywordCount", "person", "personCount"], "Keywords & People");
        same(&["title", "caption", "altText", "creator", "copyright", "copyrightStatus"], "Description");
        same(&["location", "city", "state", "country", "hasGps"], "Location");
        for f in ["rating", "flag", "label", "text"] {
            assert_eq!(field_group(f), None, "{f} stays at the top level");
        }
        assert_eq!(field_group("nope"), None);
        assert_eq!(field_label("filePath"), Some("File Path"));
        assert_eq!(field_label("nope"), None);
    }
}

//! Forgetting untouched Local browse records (see [`crate::local`]).

use std::sync::Arc;

use lightcraft_develop::DevelopSettings;

use crate::*;

const OLD: &str = "2026-08-01T10:00:00";
const NOW: &str = "2026-10-05T10:00:00";

/// A Local record of `/pics/<folder>/IMG_<i>.JPG` as a browse catalogues it (with its baseline).
fn local(c: &mut Catalog, folder: &str, i: u32) -> PhotoId {
    let id = c.alloc_photo_id();
    let mut p = Photo::new(id, Source::File { path: format!("/pics/{folder}/IMG_{i}.JPG") }, &format!("IMG_{i}.JPG"), "JPEG", 60, 40, OLD);
    p.meta.camera = "Cam".into();
    p.meta.creator = "From EXIF".into(); // file metadata is part of the baseline, not a user change
    p.focal_and_wb_for_test();
    p.local = true;
    p.set_local_baseline();
    c.apply(Op::AddPhoto { photo: Box::new(p) }).unwrap();
    id
}

impl Photo {
    fn focal_and_wb_for_test(&mut self) {
        self.meta.focal_mm = Some(35.3);
        self.as_shot_wb = Some((5123.4, 3.1));
    }
}

fn browsed(c: &mut Catalog, folder: &str, at: &str) {
    c.apply(Op::SetBrowsed { folder: format!("/pics/{folder}"), at: Some(at.into()) }).unwrap();
}

fn plan(c: &Catalog, days: u32) -> ForgetPlan {
    c.forget_local_plan(NOW, days, &|_| false)
}

fn run(c: &mut Catalog, days: u32) -> ForgetPlan {
    let p = plan(c, days);
    for op in p.ops() {
        c.apply(op).unwrap();
    }
    p
}

#[test]
fn untouched_records_of_old_folders_are_forgotten() {
    let mut c = Catalog::new();
    let old: Vec<_> = (0..5).map(|i| local(&mut c, "old", i)).collect();
    let recent: Vec<_> = (0..3).map(|i| local(&mut c, "recent", i)).collect();
    browsed(&mut c, "old", OLD);
    browsed(&mut c, "recent", "2026-10-01T09:00:00");
    // a library photo in the old folder is never a candidate
    let lib = c.alloc_photo_id();
    let mut p = Photo::new(lib, Source::File { path: "/pics/old/LIB.JPG".into() }, "LIB.JPG", "JPEG", 6, 4, OLD);
    p.set_local_baseline();
    c.apply(Op::AddPhoto { photo: Box::new(p) }).unwrap();

    let dry = plan(&c, 30);
    assert_eq!((dry.local, dry.evict.len(), dry.kept_recent), (8, 5, 3), "{dry:?}");
    assert_eq!(dry.evict, old);
    assert_eq!(c.len(), 9, "a plan changes nothing");
    let done = run(&mut c, 30);
    assert_eq!(done.evict.len(), 5);
    assert!(old.iter().all(|id| c.photo(*id).is_none()));
    assert!(recent.iter().all(|id| c.photo(*id).is_some()));
    assert!(c.photo(lib).is_some());
    // the folder has no Local records left: its time goes
    assert_eq!(done.unstamp, vec!["/pics/old".to_string()]);
    assert_eq!(c.last_browsed("/pics/old"), None);
    assert_eq!(c.last_browsed("/pics/recent/"), Some("2026-10-01T09:00:00"));
    // 0 days = never
    browsed(&mut c, "recent", OLD);
    assert!(plan(&c, 0).evict.is_empty());
    assert_eq!(plan(&c, 30).evict.len(), 3);
}

#[test]
fn any_user_change_keeps_a_record() {
    type Change = Box<dyn Fn(&mut Catalog, PhotoId)>;
    let set = |f: fn(&mut Photo)| -> Change {
        Box::new(move |c: &mut Catalog, id: PhotoId| {
            let mut p = (**c.photo(id).unwrap()).clone();
            f(&mut p);
            c.apply(Op::RemovePhoto { id }).unwrap();
            c.apply(Op::AddPhoto { photo: Box::new(p) }).unwrap();
        })
    };
    let op = |f: fn(PhotoId) -> Op| -> Change { Box::new(move |c: &mut Catalog, id: PhotoId| drop(c.apply(f(id)).unwrap())) };
    let edited = || {
        let mut d = DevelopSettings::default();
        d.light.exposure = 0.3;
        Arc::new(d)
    };
    let changes: Vec<(&str, Change)> = vec![
        ("rating", op(|id| Op::SetRating { id, rating: 3 })),
        ("flag", op(|id| Op::SetFlag { id, flag: Flag::Reject })),
        ("label", op(|id| Op::SetLabel { id, label: Some(ColorLabel::Red) })),
        ("develop", Box::new(move |c, id| drop(c.apply(Op::SetDevelop { id, settings: edited(), label: "Exposure".into(), edited: None }).unwrap()))),
        ("crop", set(|p| Arc::make_mut(&mut p.develop).crop.flip_h = true)),
        (
            "history only",
            Box::new(|c, id| {
                let step = HistoryStep { label: "Reset".into(), settings: Arc::new(DevelopSettings::default()) };
                drop(c.apply(Op::PushHistory { id, step }).unwrap())
            }),
        ),
        ("versions", set(|p| p.versions.push(Version { name: "v".into(), created: NOW.into(), settings: p.develop.clone(), auto: false }))),
        ("title", set(|p| p.meta.title = "T".into())),
        ("caption", set(|p| p.meta.caption = "C".into())),
        ("keywords", set(|p| p.meta.keywords.push("k".into()))),
        ("location", set(|p| p.meta.city = "Oslo".into())),
        ("gps", set(|p| p.meta.gps = Some((1.0, 2.0)))),
        ("copyright", set(|p| p.meta.copyright = "© me".into())),
        ("creator edit", set(|p| p.meta.creator = "Me".into())),
        ("capture time", op(|id| Op::SetCaptured { id, captured: Some("2020-01-01T00:00:00".into()) })),
        ("rename", set(|p| p.file_name = "renamed.JPG".into())),
        ("culling", op(|id| Op::SetAnalysis { id, analysis: Some(Analysis::default()) })),
        ("deleted", op(|id| Op::SetDeleted { id, deleted: true })),
        ("pick", op(|id| Op::SetFlag { id, flag: Flag::Pick })),
        (
            "album",
            Box::new(|c, id| {
                let a = c.alloc_album_id();
                let mut al = Album::new(a, "A");
                al.photos.push(id);
                drop(c.apply(Op::AddAlbum { album: al }).unwrap())
            }),
        ),
        (
            "stack",
            Box::new(|c, id| {
                let other = local(c, "elsewhere", 99);
                let s = c.alloc_stack_id();
                drop(c.apply(Op::AddStack { stack: Stack { id: s, photos: vec![id, other], collapsed: false } }).unwrap())
            }),
        ),
        (
            "virtual copy",
            Box::new(|c, id| {
                let mut v = (**c.photo(id).unwrap()).clone();
                v.id = c.alloc_photo_id();
                v.copy_of = Some(id);
                v.copy_name = Some("Copy 1".into());
                v.local = false;
                drop(c.apply(Op::AddPhoto { photo: Box::new(v) }).unwrap())
            }),
        ),
    ];
    for (what, change) in changes {
        let mut c = Catalog::new();
        let id = local(&mut c, "old", 1);
        let control = local(&mut c, "old", 2);
        browsed(&mut c, "old", OLD);
        change(&mut c, id);
        let p = plan(&c, 30);
        assert_eq!(p.evict, vec![control], "{what}: {p:?}");
        assert_eq!(p.kept_touched + p.kept_in_use, 1, "{what}: {p:?}");
        // the stamp stays: a record in the folder remains
        assert!(p.unstamp.is_empty(), "{what}");
    }
    // a change undone (back to the browse state) is untouched again
    let mut c = Catalog::new();
    let id = local(&mut c, "old", 1);
    browsed(&mut c, "old", OLD);
    let inv = c.apply(Op::SetRating { id, rating: 2 }).unwrap();
    assert!(plan(&c, 30).evict.is_empty());
    c.apply(inv).unwrap();
    assert_eq!(plan(&c, 30).evict, vec![id]);
}

/// Catalogs from before last-browsed times (and baselines): nothing is forgotten on the first
/// run — the folders are stamped now — and baseline-less records are judged by their data.
#[test]
fn upgrade_without_times_forgets_nothing_then_counts_from_then() {
    let mut c = Catalog::new();
    let a = local(&mut c, "a", 1);
    // legacy records: no baseline
    let legacy = |c: &mut Catalog, i: u32, f: fn(&mut Photo)| {
        let id = c.alloc_photo_id();
        let mut p = Photo::new(id, Source::File { path: format!("/pics/a/L{i}.JPG") }, "L.JPG", "JPEG", 6, 4, OLD);
        p.meta.camera = "Cam".into();
        p.local = true;
        f(&mut p);
        c.apply(Op::AddPhoto { photo: Box::new(p) }).unwrap();
        id
    };
    let clean = legacy(&mut c, 1, |_| {});
    let rated = legacy(&mut c, 2, |p| p.rating = 1);
    let with_creator = legacy(&mut c, 3, |p| p.meta.creator = "maybe the user".into());
    let p = run(&mut c, 30);
    assert!(p.evict.is_empty(), "{p:?}");
    assert_eq!(p.stamp, vec!["/pics/a".to_string()]);
    assert_eq!(c.last_browsed("/pics/a"), Some(NOW));
    // 30+ days later
    let later = c.forget_local_plan("2026-11-06T10:00:00", 30, &|_| false);
    let mut evict = later.evict.clone();
    evict.sort();
    assert_eq!(evict, vec![a, clean]);
    assert_eq!(later.kept_touched, 2, "{rated:?} {with_creator:?}");
}

#[test]
fn in_use_records_are_kept() {
    let mut c = Catalog::new();
